import{_ as a,o as r,c as l,a2 as i}from"./chunks/framework.CHeM0PsO.js";const t="/img/company_vs.png",m=JSON.parse('{"title":"职场选择","description":"","frontmatter":{},"headers":[],"relativePath":"interview/choose.md","filePath":"interview/choose.md","lastUpdated":null}'),o={name:"interview/choose.md"};function h(n,e,c,s,d,f){return r(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="职场选择" tabindex="-1">职场选择 <a class="header-anchor" href="#职场选择" aria-label="Permalink to &quot;职场选择&quot;">​</a></h1><h2 id="职业价值观排序" tabindex="-1">职业价值观排序 <a class="header-anchor" href="#职业价值观排序" aria-label="Permalink to &quot;职业价值观排序&quot;">​</a></h2><p>12选3 <a href="https://weread.qq.com/web/reader/46532b707210fc4f465d044k8f132430178f14e45fce0f7" target="_blank" rel="noreferrer">1</a></p><ol><li>追求创新</li><li>追求通过工作去帮助他人</li><li>追求声望和地位</li></ol><p>理由：</p><ol><li>创新是区别我与别人的唯一方法。</li><li>帮助是我能提供的真的价值。</li><li>声望与地位能反馈出我的帮助是否合适。</li></ol><h2 id="个人评估-2" tabindex="-1">个人评估 <a href="https://weread.qq.com/web/reader/46532b707210fc4f465d044kd3d322001ad3d9446802347" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#个人评估-2" aria-label="Permalink to &quot;个人评估 [2]&quot;">​</a></h2><ol><li>我的个性是什么</li><li>我的工作兴趣是什么</li><li>我在工作中的梦想是什么</li><li>我想成为什么样的人</li><li>我做人和做事的价值观是什么</li><li>我具有什么样的天赋与特长</li></ol><h2 id="工作评估" tabindex="-1">工作评估 <a class="header-anchor" href="#工作评估" aria-label="Permalink to &quot;工作评估&quot;">​</a></h2><ol><li>这个工作有非常好的发展空间吗</li><li>这个工作可长期从事吗</li><li>这个工作需要掌握一门技艺或者本领吗</li><li>这个工作有创造性、不易被取代吗</li><li>这个工作能激发我的成就感吗</li><li>这个工作符合我的性格特点和职业需求吗</li></ol><h2 id="终极评估" tabindex="-1">终极评估 <a class="header-anchor" href="#终极评估" aria-label="Permalink to &quot;终极评估&quot;">​</a></h2><ol><li>如果世界上所有工作的收入都一样,那么我会从事这个工作吗</li><li>我希望自己的孩子以后也从事这样的工作吗</li><li>如果还有十年的寿命,那么我还会从事这个工作吗</li></ol><h2 id="愿景和规划-3" tabindex="-1">愿景和规划 <a href="https://weread.qq.com/web/reader/46532b707210fc4f465d044kc7432af0210c74d97b01b1c" target="_blank" rel="noreferrer">3</a> <a class="header-anchor" href="#愿景和规划-3" aria-label="Permalink to &quot;愿景和规划 [3]&quot;">​</a></h2><p>愿景是指对未来的前景和发展方向的高度概括的描述。愿景是由核心价值观、核心目的和对未来的展望组成的。愿景最好是未来10年以上的远大目标和对目标的生动描述。稻盛和夫曾经说，要想象一个彩色的未来，越具体越好，这是成功的首要条件，不要以现在的能力束缚对未来的想象！</p><p>规划是指个人或组织制订的比较全面、长远的发展计划，是对未来整体性、长期性、基本性问题的思考和考量，是设计未来整套行动的方案。</p><h2 id="行业-4" tabindex="-1">行业 <a href="https://weread.qq.com/web/reader/46532b707210fc4f465d044k6f4322302126f4922f45dec" target="_blank" rel="noreferrer">4</a> <a class="header-anchor" href="#行业-4" aria-label="Permalink to &quot;行业 [4]&quot;">​</a></h2><p>你回过头来看看你的简历，是在一个领域、一个行业深耕多年，还是觉得哪个行业有前途就去哪个行业工作、觉得哪个领域最近受到资本市场追捧就去哪个领域工作呢？很多人跳槽漫无目的，只要有一份工作就行，只要还是做产品经理就行，只要觉得这个公司做的事情相对靠谱，商业逻辑听上去比较合理、有趣就选择加入这个公司，完全没有认真地思考过自己在经验上的积累、在行业和领域上的沉淀，导致很多行业的工作都做过，每次都要重新调研用户需求，每次都至少要花3个月的时间才能够真正地感受到用户想要什么，这样做无疑是在浪费生命。</p><p>如果你作为产品经理，非常有心计，每次都探索用户的本质需求，并且能够跨领域、跨行业地思考它们之间的共性，探索如何将在一个行业中所获得的能力迁移到另一个全新的领域，那么这也算一种成长。</p><h2 id="大公司-or-小公司" tabindex="-1">大公司 or 小公司 <a class="header-anchor" href="#大公司-or-小公司" aria-label="Permalink to &quot;大公司 or 小公司&quot;">​</a></h2><p><img src="'+t+'" alt="大公司公司的优缺点"></p><ul><li>什么公司值得去：<a href="https://www.kanzhun.com/" target="_blank" rel="noreferrer">https://www.kanzhun.com/</a></li><li>企业尽调避坑（企业状态风险等级判断风险，舆情信息检验招聘信息是否属实，股权结构、经营状况、融资情况判断公司持续性，知识产权判断创新型）常用工具：工商局企业信用信息公示系统(www.gsxt.gov.cn)<a href="https://news.dayoo.com/society/202012/31/140000_53734969.htm" target="_blank" rel="noreferrer">8</a>、企查查等<a href="https://zhuanlan.zhihu.com/p/389007507" target="_blank" rel="noreferrer">7</a></li><li>公司怎么找人才：<a href="http://www.hunt007.com/employee/searchlist.htm" target="_blank" rel="noreferrer">http://www.hunt007.com/employee/searchlist.htm</a></li></ul><h3 id="做大的几种效应-6" tabindex="-1">做大的几种效应 <a href="https://www.bilibili.com/video/BV19v411k75u?from=search&amp;seid=11494051329064518502" target="_blank" rel="noreferrer">6</a> <a class="header-anchor" href="#做大的几种效应-6" aria-label="Permalink to &quot;做大的几种效应 [6]&quot;">​</a></h3><ul><li>头部效应:一步领先步步领先,资源聚集</li><li>规模效应:边际成本递减,供/需端某物多多益善</li><li>协同效应:多种事物互相促进“一鱼多吃”</li><li>网络效应:供需同体者的同质化网络(价值正比于N^2)</li><li>多边效应:供需多方(&gt;=2)彼此强化</li></ul><h3 id="人生战略" tabindex="-1">人生战略 <a class="header-anchor" href="#人生战略" aria-label="Permalink to &quot;人生战略&quot;">​</a></h3><p>人生战略的雏形目标。<a href="https://coffee.pmcaff.com/article/2147290812813440/pmcaff?utm_source=forum&amp;newwindow=1" target="_blank" rel="noreferrer">5</a></p><ul><li>使命：让所有有价值的产品项目能不被扼杀在萌芽上。</li><li>愿景：做一款智能投研产品实现我的使命，发现别人价值，并帮助别人成长。。</li><li>战略：偏向投资、整合，为更多投资人与创业者建立桥梁。</li><li>战术：野蛮、快速试错；AI；建立更多联系。</li><li>价值观：推进科技进步，实现人类幸福。</li></ul>',26)])])}const b=a(o,[["render",h]]);export{m as __pageData,b as default};
